//! Leader check for T41b: 362 join and index statements compared with sqlite3 3.53 (STRICT),
//! generated by briefs/leader/gen_join_cases.py, plus EXPLAIN strings and the T41a cases again.
#![allow(clippy::unwrap_used, clippy::panic, clippy::cast_possible_truncation)]
use iridium::sql::{Db, Value};
use iridium::{Error, MemStorage};

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn enc(v: &Value) -> String {
    match v {
        Value::Null => "N".into(),
        Value::Int(i) => format!("I{i}"),
        Value::Real(f) => format!("R{}", f.to_bits()),
        Value::Text(t) => format!("T{}", assay::to_hex(t.as_bytes())),
        Value::Blob(b) => format!("B{}", assay::to_hex(b)),
    }
}

fn kind_ok(kind: &str, e: &Error) -> bool {
    match kind {
        "ConstraintNN" => matches!(e, Error::Constraint(m) if m.contains("NOT NULL")),
        "ConstraintU" => matches!(e, Error::Constraint(m) if m.contains("UNIQUE")),
        "Type" => matches!(e, Error::Type),
        "NoSuchTable" => matches!(e, Error::NoSuchTable),
        "NoSuchIndex" => matches!(e, Error::NoSuchTable | Error::NoSuchColumn),
        "NoSuchColumn" => matches!(e, Error::NoSuchColumn),
        "Exists" => matches!(e, Error::Exists),
        "Misuse" => matches!(e, Error::Misuse),
        "Overflow" => matches!(e, Error::Overflow),
        "Parse" => matches!(e, Error::Parse { .. }),
        "Ambiguous" => matches!(e, Error::Parse { msg, .. } if msg.contains("ambiguous")),
        _ => true,
    }
}

fn run_cases(cases: &str, min: usize) {
    let mut lines = cases.lines().peekable();
    let mut db: Option<Db<MemStorage>> = None;
    let (mut n, mut fails) = (0, Vec::new());
    while let Some(l) = lines.next() {
        if l == "NEW" {
            db = Some(Db::open(MemStorage::new(), MemStorage::new()).unwrap());
            continue;
        }
        if l == "REOPEN" {
            let (m, g) = db.take().unwrap().close().unwrap();
            db = Some(Db::open(m, g).unwrap());
            continue;
        }
        let sql = String::from_utf8(unhex(&l[2..])).unwrap();
        n += 1;
        let want = lines.next().unwrap();
        let got = db.as_mut().unwrap().execute(&sql);
        if let Some(kind) = want.strip_prefix("E ") {
            match &got {
                Err(e) if kind_ok(kind, e) => {}
                other => fails.push(format!("{sql}\n  want error {kind}, got {other:?}")),
            }
            continue;
        }
        let f: Vec<&str> = want.split(' ').collect();
        let (changes, ordered, nrows): (u64, bool, usize) =
            (f[1].parse().unwrap(), f[2] == "1", f[3].parse().unwrap());
        let cols: Vec<String> = f
            .get(4)
            .filter(|c| !c.is_empty())
            .map(|c| {
                c.split(',')
                    .map(|h| String::from_utf8(unhex(h)).unwrap())
                    .collect()
            })
            .unwrap_or_default();
        let mut want_rows: Vec<String> = (0..nrows)
            .map(|_| lines.next().unwrap()[2..].to_string())
            .collect();
        let rows = match got {
            Ok(r) => r,
            Err(e) => {
                fails.push(format!("{sql}\n  want ok, got {e:?}"));
                continue;
            }
        };
        let mut got_rows: Vec<String> = rows
            .rows
            .iter()
            .map(|r| r.iter().map(enc).collect::<Vec<_>>().join(","))
            .collect();
        if !ordered {
            want_rows.sort();
            got_rows.sort();
        }
        if sql.starts_with("SELECT") && rows.columns != cols {
            fails.push(format!(
                "{sql}\n  columns want {cols:?} got {:?}",
                rows.columns
            ));
        }
        if rows.changes != changes {
            fails.push(format!(
                "{sql}\n  changes want {changes} got {}",
                rows.changes
            ));
        }
        if got_rows != want_rows {
            fails.push(format!(
                "{sql}\n  rows want {want_rows:?}\n  got {got_rows:?}"
            ));
        }
    }
    assert!(n >= min, "only {n} statements");
    assert!(
        fails.is_empty(),
        "{} of {n} statements differ:\n{}",
        fails.len(),
        fails[..fails.len().min(8)].join("\n")
    );
}

#[test]
fn joins_match_sqlite() {
    run_cases(include_str!("join_cases.txt"), 300);
}

#[test]
fn t41a_cases_still_match() {
    run_cases(include_str!("sql_cases.txt"), 300);
}

fn plan(db: &mut Db<MemStorage>, q: &str) -> Vec<String> {
    let r = db.execute(&format!("EXPLAIN {q}")).unwrap();
    assert_eq!(r.columns, vec!["plan".to_string()], "{q}");
    r.rows
        .into_iter()
        .map(|row| match &row[..] {
            [Value::Text(t)] => t.clone(),
            other => panic!("{q}: plan row {other:?}"),
        })
        .collect()
}

#[test]
fn explain_strings() {
    let mut db = Db::open(MemStorage::new(), MemStorage::new()).unwrap();
    for s in [
        "CREATE TABLE t (id INTEGER PRIMARY KEY, a INTEGER, b INTEGER, c TEXT)",
        "CREATE INDEX iab ON t (a, b)",
        "CREATE INDEX ic ON t (c)",
        "CREATE TABLE u (id INTEGER PRIMARY KEY, tid INTEGER)",
        "CREATE INDEX ut ON u (tid)",
        "INSERT INTO t (a, b, c) VALUES (1, 2, 'x'), (1, 3, 'y'), (2, 2, NULL)",
        "INSERT INTO u (tid) VALUES (1), (1), (3)",
    ] {
        db.execute(s).unwrap();
    }
    let cases: [(&str, &[&str]); 16] = [
        ("SELECT * FROM t", &["SCAN t"]),
        ("SELECT * FROM t WHERE id = 5", &["SEARCH t USING ROWID"]),
        ("SELECT * FROM t WHERE rowid = 2", &["SEARCH t USING ROWID"]),
        (
            "SELECT * FROM t WHERE id = 5 AND a = 1",
            &["SEARCH t USING ROWID"],
        ),
        (
            "SELECT * FROM t WHERE a = 1",
            &["SEARCH t USING INDEX iab (a=?)"],
        ),
        (
            "SELECT * FROM t WHERE a = 1 AND b > 2",
            &["SEARCH t USING INDEX iab (a=? AND b>?)"],
        ),
        (
            "SELECT * FROM t WHERE b <= 2 AND a = 1",
            &["SEARCH t USING INDEX iab (a=? AND b<=?)"],
        ),
        (
            "SELECT * FROM t WHERE a = 1 AND b BETWEEN 1 AND 3",
            &["SEARCH t USING INDEX iab (a=? AND b>? AND b<?)"],
        ),
        (
            "SELECT * FROM t WHERE a = 1 AND b = 2",
            &["SEARCH t USING INDEX iab (a=? AND b=?)"],
        ),
        (
            "SELECT * FROM t WHERE a >= 1",
            &["SEARCH t USING INDEX iab (a>=?)"],
        ),
        ("SELECT * FROM t WHERE b = 1", &["SCAN t"]),
        (
            "SELECT * FROM t WHERE c = 'x'",
            &["SEARCH t USING INDEX ic (c=?)"],
        ),
        ("SELECT * FROM t WHERE a = 1 OR a = 2", &["SCAN t"]),
        ("SELECT * FROM t AS p WHERE p.a = b", &["SCAN t"]),
        (
            "SELECT * FROM t JOIN u ON u.tid = t.id",
            &["SCAN t", "SEARCH u USING INDEX ut (tid=?)"],
        ),
        (
            "SELECT * FROM u AS q LEFT JOIN t AS p ON p.id = q.tid",
            &["SCAN u", "SEARCH t USING ROWID"],
        ),
    ];
    for (q, want) in cases {
        assert_eq!(
            plan(&mut db, q),
            want.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
            "{q}"
        );
    }
    let r = db
        .execute("SELECT t.id, u.id FROM t LEFT JOIN u ON u.tid = t.id ORDER BY t.id, u.id")
        .unwrap();
    let enc: Vec<String> = r
        .rows
        .iter()
        .map(|r| r.iter().map(super_enc).collect::<Vec<_>>().join(","))
        .collect();
    assert_eq!(enc, vec!["I1,I1", "I1,I2", "I2,N", "I3,I3"]);
}

fn super_enc(v: &Value) -> String {
    enc(v)
}
